 function readingHTML(){const c=S.current(),base=new URL('./',location.href).href,ts=c.threads.filter(t=>t.visible&&t.items.length),row=(t,id)=>{const x=c.items.find(y=>y.id===id);if(!x)return '';const f=filmOf(x),links=c.links.filter(l=>l.source===id||l.target===id),th=terms(x);return `<li><h3>${esc(x.title)}</h3><p class="m">${esc([x.maker,x.year,landCaption(x)].filter(Boolean).join(' · '))}</p>${th.length?`<p class="m">Themes: ${esc(th.join(', '))}${f?.themeSource?` · <a href="${esc(f.themeSource)}">synopsis source</a>`:''}</p>`:''}${t.notes[id]?`<p>${esc(t.notes[id])}</p>`:''}${links.map(l=>`<p class="m"><b>${esc(l.label)}</b>${l.note?' · '+esc(l.note):''}${l.sourceURL?` · <a href="${esc(l.sourceURL)}">source</a>`:''}</p>`).join('')}${x.href?`<p class="m"><a href="${esc(new URL(x.href,base).href)}">Open in the atlas</a></p>`:''}</li>`;};
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(c.name)}</title><style>body{font:17px/1.55 Georgia,serif;max-width:720px;margin:40px auto;padding:0 18px;color:#1d1d1b;background:#fbfaf6}h1{font-weight:400;font-size:2em;margin:0 0 .2em}h2{font-weight:400;border-top:1px solid #ccc;padding-top:.8em;margin-top:2em}h3{margin:0;font-size:1.05em}li{margin:0 0 1.1em}.m{font:14px/1.45 system-ui,sans-serif;color:#555;margin:.2em 0}a{color:#175fac}footer{font:13px/1.5 system-ui,sans-serif;color:#555;border-top:1px solid #ccc;margin-top:2.5em;padding-top:1em}</style></head><body><h1>${esc(c.name)}</h1>${c.author?`<p class="m">Woven by ${esc(c.author)}</p>`:''}${c.note?`<p>${esc(c.note)}</p>`:''}${ts.map(t=>`<h2>${esc(t.name)}</h2>${t.description?`<p>${esc(t.description)}</p>`:''}${summary(t)?`<p class="m">${esc(summary(t))}</p>`:''}<ol>${t.items.map(id=>row(t,id)).join('')}</ol>`).join('')||'<p>No visible threads.</p>'}<footer>${esc(citation(shareURL('read')||base))}<br>Themes are tagged from each film’s published synopsis. Filmmakers, peoples and lands follow the atlas’s own sourcing.</footer></body></html>`;}

